def pix(name: str, color: str = "#A7ADB4", size: int = 18) -> "QPixmap":
    # ``currentColor`` lives on the shared outer <svg>, not inside most icon
    # fragments. Replace after composing the complete SVG so every stroke
    # keeps the exact green / muted / warning color requested by the design.
    svg = (_S + ICONS.get(name, ICONS["info"]) + "</svg>").replace("currentColor", color)
    pm = QPixmap(size, size)
    pm.fill(Qt.GlobalColor.transparent)
    r = QSvgRenderer(QByteArray(svg.encode("utf-8")))
    p = QPainter(pm)
    r.render(p)
    p.end()
    return pm


def icon(name: str, color: str = "#A7ADB4", size: int = 18) -> QIcon:
    return QIcon(pix(name, color, size))
